const ROAD_IMAGE = "data:image/webp;base64,";
const TRAVELER_IMAGE = "data:image/webp;base64,";

export function bindRoadTransition(playButton: HTMLButtonElement): void {
  const shell = document.querySelector<HTMLElement>('#game-shell');
  if (!shell || document.querySelector('#road-transition')) return;

  const overlay = document.createElement('section');
  overlay.id = 'road-transition';
  overlay.className = 'road-transition';
  overlay.setAttribute('aria-hidden', 'true');
  overlay.innerHTML = `
    <div class="road-transition__paper"></div>
    <div class="road-transition__ground"></div>
    <div class="road-transition__walker-wrap">
      <div class="road-transition__shadow"></div>
      <img class="road-transition__walker" alt="" />
    </div>
  `;

  shell.append(overlay);

  const ground = overlay.querySelector<HTMLElement>('.road-transition__ground');
  const walker = overlay.querySelector<HTMLImageElement>('.road-transition__walker');
  if (!ground || !walker) return;

  ground.style.backgroundImage = `url("${ROAD_IMAGE}")`;
  walker.src = TRAVELER_IMAGE;

  let raf = 0;
  let hideTimer = 0;
  let last = 0;
  let roadX = 0;

  const tick = (now: number): void => {
    if (!overlay.classList.contains('active')) return;
    if (last === 0) last = now;
    const dt = Math.min((now - last) / 1000, 0.05);
    last = now;
    roadX -= 190 * dt;
    ground.style.backgroundPositionX = `${roadX}px`;
    raf = requestAnimationFrame(tick);
  };

  const hide = (): void => {
    overlay.classList.remove('active');
    overlay.setAttribute('aria-hidden', 'true');
    cancelAnimationFrame(raf);
    last = 0;
  };

  const show = (duration = 3400): void => {
    window.clearTimeout(hideTimer);
    cancelAnimationFrame(raf);
    roadX = 0;
    last = 0;
    overlay.classList.add('active');
    overlay.setAttribute('aria-hidden', 'false');
    raf = requestAnimationFrame(tick);
    hideTimer = window.setTimeout(hide, duration);
  };

  playButton.addEventListener('click', () => show(), { capture: true });

  if (new URLSearchParams(window.location.search).get('roadPreview') === '1') {
    window.setTimeout(() => show(15000), 120);
  }
}
